// 掲載ページから .xlsm リンクを拾い、Ver番号を前回値と比較する。
// 判定ロジックは check_gigi_ver.py の decide() と同じ。

const html = $input.first().json.data ?? $input.first().json.body ?? '';
if (typeof html !== 'string' || html.length < 1000) {
  throw new Error('HTMLが取得できていない（長さ=' + (html?.length ?? 0) + '）');
}

// --- .xlsm リンク抽出 ---
const re = /href\s*=\s*["']((?:https?:\/\/www\.mhlw\.go\.jp)?\/content\/[^"']*?\.xlsm)["']/gi;
const links = [];
let m;
while ((m = re.exec(html)) !== null) {
  const url = m[1].startsWith('http') ? m[1] : 'https://www.mhlw.go.jp' + m[1];
  if (!links.includes(url)) links.push(url);
}

// ページ改修は黙って進めず必ず止める
if (links.length === 0) {
  throw new Error('ページに .xlsm リンクが無い。掲載場所が変わった可能性あり: ' + $('掲載ページ取得').params.url);
}
if (links.length > 1) {
  throw new Error('.xlsm リンクが複数ある(' + links.length + '件)。どれが疑義解釈ツールか判定不能: ' + JSON.stringify(links));
}

const url = links[0];
const fname = url.split('/').pop();

// --- Ver パース ---
const vm = fname.match(/Ver\.?\s*(\d+(?:\.\d+)*)\.?/i);
if (!vm) {
  throw new Error('ファイル名からVerが読めない: ' + fname);
}
const ver = vm[1];
const toTuple = (s) => s.split('.').map(Number);

// --- 前回状態 ---
const store = $getWorkflowStaticData('global');
const prevVer = store.gigiVer ?? null;

function compare(a, b) {
  if (b === null) return 'first_run';
  const A = toTuple(a), B = toTuple(b);
  const n = Math.max(A.length, B.length);
  for (let i = 0; i < n; i++) {
    const x = A[i] ?? 0, y = B[i] ?? 0;
    if (x > y) return 'new_version';
    if (x < y) return 'ver_downgrade';
  }
  return 'no_change';
}

const status = compare(ver, prevVer);

// Verが下がるのは異常。上書きせず人間に投げる
if (status === 'ver_downgrade') {
  throw new Error('Verが退行している: ' + prevVer + ' -> ' + ver + ' （差し戻し or 誤検知。要確認）');
}

const reasons = {
  first_run: '初回実行。現在のVerを記録する',
  new_version: 'Verが ' + prevVer + ' → ' + ver + ' に上がった（疑義解釈が1回分追加された）',
  no_change: 'Verは ' + ver + ' のまま',
};

return [{
  json: {
    status,
    url,
    filename: fname,
    ver,
    prev_ver: prevVer,
    reason: reasons[status],
    is_new: status === 'new_version' || status === 'first_run',
    checked_at: new Date().toISOString(),
  },
}];

// Verが据え置きのまま中身だけ差し替えられたケースを拾う。
// Last-Modified / Content-Length のどちらかが動いていたら silent_update 候補。

const prev = $('Verを抽出して前回と比較').first().json;
const res = $input.first().json;
const headers = res.headers ?? {};

const lm = headers['last-modified'] ?? null;
const cl = headers['content-length'] ?? null;

const store = $getWorkflowStaticData('global');
const prevLm = store.gigiLastModified ?? null;
const prevCl = store.gigiContentLength ?? null;

// ヘッダが取れないときは判定できないので安全側（変化ありとみなす）
const unknown = lm === null || cl === null || prevLm === null || prevCl === null;
const changed = unknown || String(lm) !== String(prevLm) || String(cl) !== String(prevCl);

// 記録は毎回更新する
store.gigiLastModified = lm;
store.gigiContentLength = cl;
store.gigiLastCheckedAt = new Date().toISOString();

return [{
  json: {
    ...prev,
    status: changed ? 'silent_update_suspect' : 'no_change',
    last_modified: lm,
    content_length: cl,
    prev_last_modified: prevLm,
    prev_content_length: prevCl,
    header_unknown: unknown,
    needs_human_review: changed,
    reason: changed
      ? 'Verは据え置きだが配信ファイルのメタ情報が動いた。中身の差し替えの可能性あり'
      : 'Ver・ファイルとも変化なし',
  },
}];

const j = $input.first().json;
const store = $getWorkflowStaticData('global');

store.gigiVer = j.ver;
store.gigiUrl = j.url;
store.gigiLastCheckedAt = j.checked_at;
store.gigiHistory = (store.gigiHistory ?? []).concat([
  { ver: j.ver, prev_ver: j.prev_ver, detected_at: j.checked_at },
]).slice(-50);

return [{
  json: {
    ...j,
    next_action: 'python load_gigi.py --xlsm data/gigi/' + j.filename + ' --db med_code_map.db',
    note: 'ダウンロードと取込はmed-code-map側で実行する。取込後、gigi_source テーブルの ver がこのVerと一致することを確認すること。',
  },
}];
